source('code/00_config.R');suppressPackageStartupMessages(library(limma))
m<-readRDS(path('metadata/analysis_metadata.rds'));B<-rd(path('audit/metric_validation.tsv'))$GENE_mean_count
oldroot<-file.path(PREVIOUS,'results/profile');portable<-path('results/profile/exact_count_inputs');dir.create(portable,showWarnings=FALSE)
if(!all(file.exists(file.path(portable,paste0(m$sample_id,'.rds'))))&&!all(file.exists(file.path(oldroot,'checkpoints',paste0(m$sample_id,'.recount.rds')))))source('code/05a_profile_from_BED.R')
exfile<-if(file.exists(path('results/profile/annotation_exposure.tsv')))path('results/profile/annotation_exposure.tsv')else file.path(oldroot,'annotation_exposure.tsv');ex<-rd(exfile)[,.(region,bin,annotation_bp,transcript_bins)]
ans<-lapply(m$sample_id,function(id){out<-file.path(portable,paste0(id,'.rds'));f<-if(file.exists(out))out else file.path(oldroot,'checkpoints',paste0(id,'.recount.rds'));stopifnot(file.exists(f));z<-as.data.table(readRDS(f));stopifnot(nrow(z)==150,all(z$count>=0),all(z$count==floor(z$count)));z<-z[,.(sample_id,region,bin,position,count,transcript_bins)];if(!file.exists(out))saveRDS(z,out,compress=FALSE);z[,`:=`(Ri=count/B,mean_count=count/transcript_bins)];z})
d<-rbindlist(ans);d<-merge(d,ex[,.(region,bin,annotation_bp)],by=c('region','bin'));d[,density_per_million_bp:=count/annotation_bp*1e6];wr(d,path('results/profile/participant_bins.tsv'));wr(ex,path('results/profile/annotation_exposure.tsv'))
inputs<-data.table(sample_id=m$sample_id,source=file.path(portable,paste0(m$sample_id,'.rds')));inputs[,md5:=unname(tools::md5sum(source))];wr(inputs,path('audit/profile_exact_integer_inputs.tsv'))
curves<-list();for(grouping in c('source_group','pathology_group')){dm<-if(grouping=='source_group')m else m[included_B==TRUE];for(g in unique(dm[[grouping]])){z<-d[sample_id%in%dm[get(grouping)==g,sample_id]];for(metric in c('Ri','mean_count','density_per_million_bp')){mat<-dcast(z,sample_id~position,value.var=metric);v<-as.matrix(mat[,-1]);set.seed(SEED);boot<-replicate(2000,colMeans(v[sample.int(nrow(v),nrow(v),replace=TRUE),,drop=FALSE]));curves[[paste(grouping,g,metric)]]<-data.table(grouping=grouping,group=g,metric=metric,position=1:150,n=nrow(v),mean=colMeans(v),CI_low=apply(boot,1,quantile,.025),CI_high=apply(boot,1,quantile,.975))}}}
wr(rbindlist(curves),path('results/profile/group_curves.tsv'))
tests<-list();for(level in c('bin','region')){tt<-if(level=='bin')d[,.(sample_id,feature=paste0(region,':',bin),value=Ri)]else d[,.(value=sum(Ri)),by=.(sample_id,feature=region)];wide<-dcast(tt,feature~sample_id,value.var='value');Y<-log2(as.matrix(wide[,-1])+1);colnames(Y)<-names(wide)[-1]
 for(task in c('source','pathology')){dd<-if(task=='source')m[complete_primary==TRUE]else m[complete_primary==TRUE & included_B==TRUE];dd[,sex:=factor(sex)];dd[,`:=`(is_pos=as.integer(pathology_group==G3[2]),is_neg=as.integer(pathology_group==G3[3]))];formula<-if(task=='source')~case+age_years+sex+log10_D+polya_retention else ~is_pos+is_neg+age_years+sex+log10_D+polya_retention;X<-model.matrix(formula,dd);ff<-lmFit(Y[,dd$sample_id,drop=FALSE],X);contr<-if(task=='source')list(Disease_vs_HC=c(case=1))else list(Positive_vs_HC=c(is_pos=1),Negative_vs_HC=c(is_neg=1),Positive_vs_Negative=c(is_pos=1,is_neg=-1));C<-matrix(0,nrow=ncol(X),ncol=length(contr),dimnames=list(colnames(X),names(contr)));for(k in seq_along(contr))C[names(contr[[k]]),k]<-contr[[k]];ff<-eBayes(contrasts.fit(ff,C),trend=TRUE,robust=TRUE)
  for(k in seq_along(contr)){se<-ff$stdev.unscaled[,k]*sqrt(ff$s2.post);cr<-qt(.975,ff$df.total);tests[[paste(level,task,k)]]<-data.table(level=level,task=task,feature=wide$feature,contrast=names(contr)[k],n=nrow(dd),beta=ff$coefficients[,k],CI_low=ff$coefficients[,k]-cr*se,CI_high=ff$coefficients[,k]+cr*se,P=ff$p.value[,k])}
 }}
t<-rbindlist(tests);t[,FDR:=p.adjust(P,'BH'),by=.(level,task)];wr(t,path('results/profile/adjusted_tests.tsv'))
logstage('profile','PASS exact saved participant counts reaggregated; new Ri denominator, bootstrap and adjusted tests')
